-- 047: ZooTampa at Lowry Park, Tampa, Florida (Carter, 2026-10-17, from RCDB;
-- 28.0138403002091, -82.46995230757814). Not in D1 before. All three removed.
--   Magic Dragon     Allan Herschell Little Dipper kiddie, 8/1960 - >=1987
--                    (stored as 1987); formerly "Roller Coaster"
--   Tasmanian Tiger  Wisdom Dragon Wagon, 12/2008 - 2/2026. RCDB: this is Tiger
--                    Terror from Wild Adventures (041), so the two are linked
--                    as one ride, home here (the later park). Nobody has
--                    ridden Tiger Terror, so no count moves.
--   Dragon Wagon     Wisdom Dragon Wagon (oval), 1996. RCDB names it "unknown";
--                    a ride called "unknown" reads like missing data, so it is
--                    named for its model.
-- Both Wisdom rides join the Dragon Wagons category. /changes rows in the
-- Worker's shapes. Safe to run twice.
INSERT INTO parks (name, lat, lon, region) SELECT 'ZooTampa at Lowry Park', 28.0138403002091, -82.46995230757814, 'Florida, US' WHERE NOT EXISTS (SELECT 1 FROM parks WHERE name = 'ZooTampa at Lowry Park');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, laps, yr, opened, openedPrec, closed, closedPrec) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Magic Dragon', 'ZooTampa at Lowry Park', 'Steel', 'Allan Herschell', 'Allan Herschell Little Dipper', NULL, NULL, NULL, 0, NULL, 1, 1960, '1960-08', 'month', '1987', 'year' WHERE EXISTS (SELECT 1 FROM parks WHERE name = 'ZooTampa at Lowry Park') AND NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Magic Dragon' AND park = 'ZooTampa at Lowry Park');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, laps, yr, opened, openedPrec, closed, closedPrec) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Tasmanian Tiger', 'ZooTampa at Lowry Park', 'Steel', 'Wisdom Rides', 'Wisdom Dragon Wagon', NULL, NULL, NULL, 0, NULL, 1, 2008, '2008-12', 'month', '2026-02', 'month' WHERE EXISTS (SELECT 1 FROM parks WHERE name = 'ZooTampa at Lowry Park') AND NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Tasmanian Tiger' AND park = 'ZooTampa at Lowry Park');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, laps, yr, opened, openedPrec, closed, closedPrec) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Dragon Wagon', 'ZooTampa at Lowry Park', 'Steel', 'Wisdom Rides', 'Wisdom Dragon Wagon', NULL, NULL, NULL, 0, NULL, 1, 1996, '1996', 'year', '1996', 'year' WHERE EXISTS (SELECT 1 FROM parks WHERE name = 'ZooTampa at Lowry Park') AND NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Dragon Wagon' AND park = 'ZooTampa at Lowry Park');
INSERT OR IGNORE INTO coaster_aliases (coaster_id, former_name, note, added) SELECT id, 'Roller Coaster', 'rcdb', date('now') FROM coasters WHERE name = 'Magic Dragon' AND park = 'ZooTampa at Lowry Park';
INSERT OR IGNORE INTO clone_members (coaster, group_id) SELECT c.id, g.id FROM coasters c, clone_groups g WHERE g.name = 'Dragon Wagons' AND c.park = 'ZooTampa at Lowry Park' AND c.name IN ('Tasmanian Tiger', 'Dragon Wagon');
INSERT OR IGNORE INTO same_ride (coaster, ride) SELECT x.id, t.id FROM coasters t, coasters x WHERE t.name = 'Tasmanian Tiger' AND t.park = 'ZooTampa at Lowry Park' AND ((x.name = 'Tiger Terror' AND x.park = 'Wild Adventures') OR x.id = t.id);
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.park = 'ZooTampa at Lowry Park' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND a.subject = c.name AND json_extract(a.detail, '$.park') = 'ZooTampa at Lowry Park');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'clone_set', g.name, (SELECT COUNT(*) FROM clone_members m WHERE m.group_id = g.id), json_object('made', 0, 'via', '047') FROM clone_groups g WHERE g.name = 'Dragon Wagons' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'clone_set' AND a.subject = g.name AND a.detail LIKE '%"via":"047"%');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'same_ride_set', h.name, (SELECT COUNT(*) FROM same_ride s WHERE s.ride = h.id), json_object('ride', h.id, 'at', (SELECT json_group_array(json_object('id', c.id, 'park', c.park, 'name', c.name)) FROM coasters c JOIN same_ride s ON s.coaster = c.id WHERE s.ride = h.id), 'via', '047') FROM coasters h WHERE h.name = 'Tasmanian Tiger' AND h.park = 'ZooTampa at Lowry Park' AND EXISTS (SELECT 1 FROM same_ride s WHERE s.ride = h.id) AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'same_ride_set' AND a.detail LIKE '%"via":"047"%');
